    def collect_snapshot(self, **kwargs):
        """
        Function to collect snapshot
        """
        logcoverage = kwargs.get("logcoverage", "all")
        snapshotfilename = kwargs.get("snapshotfilename", None)
        notes = kwargs.get("notes", None)
        notesfile = kwargs.get("notesfile", None)
        cancel_after = kwargs.get("cancel_after", None)
        lnceldn = kwargs.get("lnceldn", None)
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["logcoverage", "snapshotfilename", "notes", "notesfile",
                              "cancel_after", "lnceldn"]}
        self.oam_tool.save_snapshot(logcoverage=logcoverage, snapshotfilename=snapshotfilename,
                                    notes=notes, notesfile=notesfile, cancel_after=cancel_after,
                                    lnceldn=lnceldn, **kwargs)

    def reset_bts(self, **kwargs):
        """
        Function to reset bts
        """
        if not kwargs.get("params", None):
            self._reset_bts_rad_parameters(**kwargs)
        elif not kwargs.get("handover", False):
            self._reset_bts_with_handover(**kwargs)
        elif not (kwargs.get("handover", False) and kwargs.get("params", None)):
            self._reset_bts(**kwargs)

    def _reset_bts_rad_parameters(self, **kwargs):
        params = kwargs.get("params", None)
        timeout = kwargs.get("timeout", "15min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["params", "timeout"]}
        self.oam_tool.reset_bts_rad_parameters(params=params, timeout=timeout, **kwargs)

    def _reset_bts_with_handover(self, **kwargs):
        coverage = kwargs.get("coverage", "site")
