    def generate_scf(self, **kwargs):
        """
        Function to generate scf
        """
        filename = kwargs.get("filename", None)
        ssh = kwargs.get("ssh", "toor4nsn:oZPS0POrRieRtu")
        timeout = kwargs.get("timeout", "15min")
        export_type = kwargs.get("export_type", "bts")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["timeout", "ssh", "filename"]}
        if export_type.lower() == "bts":
            self.oam_tool.upload_bts_scfc_file(filename=filename, ssh=ssh, timeout=timeout,
                                               **kwargs)
        elif export_type.lower() == "trs":
            self.oam_tool.upload_trs_scf_bts_file(ssh=ssh, timeout=timeout, **kwargs)

